//! Unicode character data as JDK 11 has it.
//!
//! A JDK carries the Unicode version it shipped with — 11 carries Unicode 10 —
//! while Rust's tables track the current one. Deriving `Character.isLetter`
//! and friends from Rust therefore disagreed with a real JDK on 4761 BMP
//! units: Georgian Mtavruli and the other additions of Unicode 11 onwards, and
//! a category-model difference over combining marks. Everything below U+0295
//! agreed, so ASCII and Latin-1 never showed it.
//!
//! So the categories are carried here instead of derived, which also makes
//! these predicates independent of the Rust toolchain's Unicode version.
//! Recorded from a real JDK 11 with `Character.getType` over the whole BMP;
//! the whole-BMP agreement is pinned as a differential test.

/// The general category of each BMP code point, as the START of a run —
/// entry `i` covers up to the code point before entry `i + 1`. The runs are
/// contiguous and cover U+0000..=U+FFFF, so only the start needs storing.
