/// `isWhitespace` is NOT the separator categories: it adds the ASCII control
/// whitespace and file/group/record/unit separators, and REMOVES the
/// non-breaking spaces (a JDK calls those space characters but not
/// whitespace).
static WHITESPACE_EXTRA: &[(u32, u32)] = &[(0x0000_0009, 0x0000_000D), (0x0000_001C, 0x0000_001F)];

static WHITESPACE_EXCLUDED: &[(u32, u32)] = &[
    (0x0000_00A0, 0x0000_00A0),
    (0x0000_2007, 0x0000_2007),
    (0x0000_202F, 0x0000_202F),
];

fn in_ranges(table: &[(u32, u32)], unit: u32) -> bool {
    table
        .binary_search_by(|(first, last)| {
            if unit < *first {
                std::cmp::Ordering::Greater
            } else if unit > *last {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// The same, for the code points ABOVE the BMP — so a category question is
