/// The general category of a CODE POINT.
#[must_use]
pub fn category_of(point: u32) -> u8 {
    let Ok(unit) = u16::try_from(point) else {
        if point > 0x10_FFFF {
            return UNASSIGNED;
        }
        let at = match SUPPLEMENTARY_CATEGORY_RUNS.binary_search_by_key(&point, |(start, _)| *start)
        {
            Ok(at) => at,
            Err(0) => return UNASSIGNED,
            Err(after) => after - 1,
        };
        return SUPPLEMENTARY_CATEGORY_RUNS[at].1;
    };
    category(unit)
}

/// `Character.getType` for one UTF-16 unit — a surrogate has a category too.
#[must_use]
pub fn category(unit: u16) -> u8 {
    let at = match CATEGORY_RUNS.binary_search_by_key(&unit, |(start, _)| *start) {
        Ok(at) => at,
        Err(0) => return 0,
        Err(after) => after - 1,
    };
    CATEGORY_RUNS[at].1
}

const UPPERCASE_LETTER: u8 = 1;
const LOWERCASE_LETTER: u8 = 2;
const TITLECASE_LETTER: u8 = 3;
const MODIFIER_LETTER: u8 = 4;
const OTHER_LETTER: u8 = 5;
const DECIMAL_DIGIT_NUMBER: u8 = 9;
const LETTER_NUMBER: u8 = 10;
const SPACE_SEPARATOR: u8 = 12;
const LINE_SEPARATOR: u8 = 13;
const PARAGRAPH_SEPARATOR: u8 = 14;
const NON_SPACING_MARK: u8 = 6;
const COMBINING_SPACING_MARK: u8 = 8;
const FORMAT: u8 = 16;
const CONNECTOR_PUNCTUATION: u8 = 23;
const CURRENCY_SYMBOL: u8 = 26;
const UNASSIGNED: u8 = 0;

/// `Character.isLetter`: the five letter categories and nothing else —
/// `LETTER_NUMBER` is alphabetic but NOT a letter.
#[must_use]
pub fn is_letter(point: u32) -> bool {
    matches!(
        category_of(point),
        UPPERCASE_LETTER | LOWERCASE_LETTER | TITLECASE_LETTER | MODIFIER_LETTER | OTHER_LETTER
    )
}

#[must_use]
pub fn is_digit(point: u32) -> bool {
    category_of(point) == DECIMAL_DIGIT_NUMBER
}

#[must_use]
pub fn is_upper(point: u32) -> bool {
    category_of(point) == UPPERCASE_LETTER || in_ranges(OTHER_UPPERCASE, point)
}

#[must_use]
pub fn is_lower(point: u32) -> bool {
    category_of(point) == LOWERCASE_LETTER || in_ranges(OTHER_LOWERCASE, point)
}

#[must_use]
pub fn is_alphabetic(point: u32) -> bool {
    matches!(
        category_of(point),
        UPPERCASE_LETTER
            | LOWERCASE_LETTER
            | TITLECASE_LETTER
            | MODIFIER_LETTER
            | OTHER_LETTER
            | LETTER_NUMBER
    ) || in_ranges(OTHER_ALPHABETIC, point)
}

#[must_use]
pub fn is_defined(point: u32) -> bool {
    category_of(point) != UNASSIGNED
}

#[must_use]
pub fn is_space_char(point: u32) -> bool {
    matches!(
        category_of(point),
        SPACE_SEPARATOR | LINE_SEPARATOR | PARAGRAPH_SEPARATOR
    )
}

#[must_use]
pub fn is_whitespace(point: u32) -> bool {
    if in_ranges(WHITESPACE_EXTRA, point) {
        return true;
    }
    is_space_char(point) && !in_ranges(WHITESPACE_EXCLUDED, point)
}

/// `Character.isMirrored`.
#[must_use]
pub fn is_mirrored(point: u32) -> bool {
    in_ranges(MIRRORED, point)
}

/// `Character.isIdeographic`.
#[must_use]
pub fn is_ideographic(point: u32) -> bool {
    in_ranges(IDEOGRAPHIC, point)
}

/// `Character.isTitleCase` — the CATEGORY, not a coincidence of the case
/// mappings, which is how this was derived and which answered `true` for
/// every character whose title form is itself.
#[must_use]
pub fn is_title_case(point: u32) -> bool {
    category_of(point) == TITLECASE_LETTER
}

/// `Character.isISOControl`.
#[must_use]
pub fn is_iso_control(point: u32) -> bool {
    matches!(point, 0..=0x1F | 0x7F..=0x9F)
}

/// `Character.isIdentifierIgnorable` — the ISO control characters that are
/// NOT whitespace, plus every format character.
#[must_use]
pub fn is_identifier_ignorable(point: u32) -> bool {
    matches!(point, 0x00..=0x08 | 0x0E..=0x1B | 0x7F..=0x9F) || category_of(point) == FORMAT
}

/// Five CJK ideographs a JDK 11 calls letters and refuses as identifiers.
/// `Character.getType` puts U+9FEB..U+9FEF in `OTHER_LETTER` — they were
/// assigned in Unicode 10, which is the version JDK 11 carries — while the
/// separate table behind the identifier predicates was not extended to cover
/// them. Deriving the predicates from the category is right everywhere else
/// in the BMP, so the exception is written down rather than the rule bent.
const JDK_NON_IDENTIFIER_LETTERS: std::ops::RangeInclusive<u32> = 0x9FEB..=0x9FEF;

/// `Character.isJavaIdentifierStart`: a letter, a letter-number, a CURRENCY
/// symbol or a CONNECTING punctuation — which is where `$` and `_` come from,
/// and not a list of two characters.
#[must_use]
pub fn is_java_identifier_start(point: u32) -> bool {
    if JDK_NON_IDENTIFIER_LETTERS.contains(&point) {
        return false;
    }
    is_letter(point)
        || matches!(
            category_of(point),
            LETTER_NUMBER | CURRENCY_SYMBOL | CONNECTOR_PUNCTUATION
        )
}

/// `Character.isJavaIdentifierPart`.
#[must_use]
pub fn is_java_identifier_part(point: u32) -> bool {
    if JDK_NON_IDENTIFIER_LETTERS.contains(&point) {
        return false;
    }
    is_letter(point)
        || matches!(
            category_of(point),
            LETTER_NUMBER
                | CURRENCY_SYMBOL
                | CONNECTOR_PUNCTUATION
                | DECIMAL_DIGIT_NUMBER
                | COMBINING_SPACING_MARK
                | NON_SPACING_MARK
        )
        || is_identifier_ignorable(point)
}

/// `Character.isUnicodeIdentifierStart`.
#[must_use]
pub fn is_unicode_identifier_start(point: u32) -> bool {
    is_letter(point) || category_of(point) == LETTER_NUMBER
}

/// `Character.isUnicodeIdentifierPart`.
#[must_use]
pub fn is_unicode_identifier_part(point: u32) -> bool {
    is_letter(point)
        || matches!(
            category_of(point),
            LETTER_NUMBER
                | CONNECTOR_PUNCTUATION
                | DECIMAL_DIGIT_NUMBER
                | COMBINING_SPACING_MARK
                | NON_SPACING_MARK
        )
        || is_identifier_ignorable(point)
}

// ---------------------------------------------------------------------------
// Grapheme clusters
// ---------------------------------------------------------------------------

/// The grapheme break property of a code point, as `java.util.regex.Grapheme`
/// derives it: from the general category, plus a handful of ranges named in
/// Unicode Annex #29. There is no table of its own — every case below is one
/// case of the JDK's, in the same order.
const GRAPHEME_OTHER: u8 = 0;
const GRAPHEME_CR: u8 = 1;
const GRAPHEME_LF: u8 = 2;
const GRAPHEME_CONTROL: u8 = 3;
const GRAPHEME_EXTEND: u8 = 4;
const GRAPHEME_RI: u8 = 5;
const GRAPHEME_PREPEND: u8 = 6;
const GRAPHEME_SPACINGMARK: u8 = 7;
const GRAPHEME_L: u8 = 8;
const GRAPHEME_V: u8 = 9;
const GRAPHEME_T: u8 = 10;
const GRAPHEME_LV: u8 = 11;
const GRAPHEME_LVT: u8 = 12;

/// Annex #29 lists these as spacing marks and then excludes them again.
fn is_excluded_spacing_mark(point: u32) -> bool {
    matches!(
        point,
        0x102B | 0x102C
            | 0x1038
            | 0x1062..=0x106D
            | 0x1083
            | 0x1087..=0x108C
            | 0x108F
            | 0x109A..=0x109C
            | 0x1A61
            | 0x1A63
            | 0x1A64
            | 0xAA7B
            | 0xAA7D
    )
}

fn grapheme_type(point: u32) -> u8 {
    const SYLLABLE_BASE: u32 = 0xAC00;
    const T_COUNT: u32 = 28;
    const S_COUNT: u32 = 19 * 21 * T_COUNT;
    match category_of(point) {
        // CONTROL
        15 => match point {
            0x000D => GRAPHEME_CR,
            0x000A => GRAPHEME_LF,
            _ => GRAPHEME_CONTROL,
        },
        // UNASSIGNED — with the one code point the JDK types as "other"
        // to agree with its own test data.
        0 if point == 0x0378 => GRAPHEME_OTHER,
        0 | 13 | 14 | 19 => GRAPHEME_CONTROL,
        // FORMAT: the zero-width joiner and non-joiner EXTEND.
        16 => {
            if matches!(point, 0x200C | 0x200D) {
                GRAPHEME_EXTEND
            } else {
                GRAPHEME_CONTROL
            }
        }
        // NON_SPACING_MARK, ENCLOSING_MARK
        6 | 7 => GRAPHEME_EXTEND,
        // COMBINING_SPACING_MARK
        8 => {
            if is_excluded_spacing_mark(point) {
                GRAPHEME_OTHER
            } else {
                GRAPHEME_SPACINGMARK
            }
        }
        // OTHER_SYMBOL: the regional indicators, which pair into a flag.
        28 => {
            if (0x0001_F1E6..=0x0001_F1FF).contains(&point) {
                GRAPHEME_RI
            } else {
                GRAPHEME_OTHER
            }
        }
        // MODIFIER_LETTER: the halfwidth voiced sound marks.
        4 => {
            if matches!(point, 0xFF9E | 0xFF9F) {
                GRAPHEME_EXTEND
            } else {
                GRAPHEME_OTHER
            }
        }
        // OTHER_LETTER: the Thai and Lao vowels, and Hangul.
        5 => {
            if matches!(point, 0x0E33 | 0x0EB3) {
                return GRAPHEME_SPACINGMARK;
            }
            if (0x1100..=0x11FF).contains(&point) {
                return if point <= 0x115F {
                    GRAPHEME_L
                } else if point <= 0x11A7 {
                    GRAPHEME_V
                } else {
                    GRAPHEME_T
                };
            }
            if let Some(index) = point.checked_sub(SYLLABLE_BASE)
                && index < S_COUNT
            {
                return if index % T_COUNT == 0 {
                    GRAPHEME_LV
                } else {
                    GRAPHEME_LVT
                };
            }
            match point {
                0xA960..=0xA97C => GRAPHEME_L,
                0xD7B0..=0xD7C6 => GRAPHEME_V,
                0xD7CB..=0xD7FB => GRAPHEME_T,
                _ => GRAPHEME_OTHER,
            }
        }
        _ => GRAPHEME_OTHER,
    }
}

/// Whether an extended grapheme cluster boundary falls BETWEEN two code
/// points — Annex #29's rules GB3 to GB10, as the JDK arranges them.
#[must_use]
pub fn grapheme_boundary(before: u32, after: u32) -> bool {
    let left = grapheme_type(before);
    let right = grapheme_type(after);
    // GB4 and GB5: a control, a CR or an LF breaks on both sides...
    if matches!(right, GRAPHEME_CR | GRAPHEME_LF | GRAPHEME_CONTROL)
        || matches!(left, GRAPHEME_CR | GRAPHEME_LF | GRAPHEME_CONTROL)
    {
        // GB3: ... except between a CR and its LF.
        return !(left == GRAPHEME_CR && right == GRAPHEME_LF);
    }
    // GB9, GB9a, GB9b: nothing breaks before an extender or a spacing mark,
    // and nothing breaks after a prepend.
    if matches!(right, GRAPHEME_EXTEND | GRAPHEME_SPACINGMARK) || left == GRAPHEME_PREPEND {
        return false;
    }
    // GB6, GB7, GB8: the Hangul syllable shapes. GB8a: two regional
    // indicators are one flag.
    !matches!(
        (left, right),
        (
            GRAPHEME_L,
            GRAPHEME_L | GRAPHEME_V | GRAPHEME_LV | GRAPHEME_LVT
        ) | (GRAPHEME_LV | GRAPHEME_V, GRAPHEME_V | GRAPHEME_T)
            | (GRAPHEME_LVT | GRAPHEME_T, GRAPHEME_T)
            | (GRAPHEME_RI, GRAPHEME_RI)
    )
}

