/// Which script a BMP code point belongs to, as an index into `SCRIPT_NAMES`.
#[must_use]
pub fn script_of(unit: u16) -> u8 {
    let at = match SCRIPT_RUNS.binary_search_by_key(&unit, |(start, _)| *start) {
        Ok(at) => at,
        Err(0) => return 0,
        Err(after) => after - 1,
    };
    SCRIPT_RUNS[at].1
}

/// `UnicodeScript.forName`: the four-letter code, or the enum's own name.
/// Both are matched without regard to case, and nothing else is.
#[must_use]
pub fn script_by_name(name: &str) -> Option<u8> {
    let upper = name.to_ascii_uppercase();
    if let Some((_, index)) = SCRIPT_ALIASES.iter().find(|(alias, _)| *alias == upper) {
        return Some(*index);
    }
    SCRIPT_NAMES
        .iter()
        .position(|script| *script == upper)
        .and_then(|index| u8::try_from(index).ok())
}

/// Which block a BMP code point is in, if any — the unassigned gaps between
/// blocks belong to none.
#[must_use]
pub fn block_of(unit: u16) -> Option<u16> {
    let at = BLOCK_RANGES
        .binary_search_by(|(first, last, _)| {
            if unit < *first {
                std::cmp::Ordering::Greater
            } else if unit > *last {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .ok()?;
    Some(BLOCK_RANGES[at].2)
}

/// `UnicodeBlock.forName`.
#[must_use]
pub fn block_by_name(name: &str) -> Option<u16> {
    let key: String = name
        .to_ascii_uppercase()
        .chars()
        .filter(|c| *c != ' ' && *c != '_')
        .collect();
    BLOCK_KEYS
        .iter()
        .find(|(alias, _)| *alias == key)
        .map(|(_, index)| *index)
}

