/// `Character.toTitleCase` where it differs from `toUpperCase` — the digraphs
/// whose title form capitalises only the first letter (`ǳ` -> `ǲ`, not `Ǳ`).
static TITLE_CASE: &[(u16, u16)] = &[
    (0x01C4, 0x01C5),
    (0x01C5, 0x01C5),
    (0x01C6, 0x01C5),
    (0x01C7, 0x01C8),
    (0x01C8, 0x01C8),
    (0x01C9, 0x01C8),
    (0x01CA, 0x01CB),
    (0x01CB, 0x01CB),
    (0x01CC, 0x01CB),
    (0x01F1, 0x01F2),
    (0x01F2, 0x01F2),
    (0x01F3, 0x01F2),
];

fn simple_entry(unit: u16) -> Option<(u16, u16)> {
    SIMPLE_CASE
        .binary_search_by_key(&unit, |(from, _, _)| *from)
        .ok()
        .map(|at| (SIMPLE_CASE[at].1, SIMPLE_CASE[at].2))
}

/// `Character.toUpperCase`.
#[must_use]
pub fn simple_upper(unit: u16) -> u16 {
    simple_entry(unit).map_or(unit, |(upper, _)| upper)
}

/// `Character.toLowerCase`.
#[must_use]
pub fn simple_lower(unit: u16) -> u16 {
    simple_entry(unit).map_or(unit, |(_, lower)| lower)
}

/// `Character.toTitleCase`.
#[must_use]
pub fn title_case(unit: u16) -> u16 {
    match TITLE_CASE.binary_search_by_key(&unit, |(from, _)| *from) {
        Ok(at) => TITLE_CASE[at].1,
        Err(_) => simple_upper(unit),
    }
}

fn full_entry(unit: u16) -> Option<(&'static [u16], &'static [u16])> {
    FULL_CASE
        .binary_search_by_key(&unit, |(from, _, _)| *from)
        .ok()
        .map(|at| (FULL_CASE[at].1, FULL_CASE[at].2))
}

/// One unit uppercased the way `String.toUpperCase` does — the FULL mapping,
/// which may be several characters.
#[must_use]
pub fn full_upper(unit: u16) -> Vec<u16> {
    match full_entry(unit) {
        Some((upper, _)) => upper.to_vec(),
        None => vec![simple_upper(unit)],
    }
}

/// One unit lowercased the way `String.toLowerCase` does.
#[must_use]
pub fn full_lower(unit: u16) -> Vec<u16> {
    match full_entry(unit) {
        Some((_, lower)) => lower.to_vec(),
        None => vec![simple_lower(unit)],
    }
}
